package app.silkquest.companion;
import android.content.Context;import org.json.*;import java.nio.file.*;import java.io.*;import java.lang.reflect.*;
public class ModelTests {
 static int count;static void check(boolean ok,String m){if(!ok)throw new AssertionError(m);count++;}
 static JSONObject op(String kind,String target)throws Exception{return new JSONObject().put("kind",kind).put("entity","quest").put("target",target);}
 static JSONObject view(Context c)throws Exception{return new JSONObject(MobileStore.view(c));}
 static JSONObject state(Context c)throws Exception{return view(c).getJSONObject("state");}
 static void forget()throws Exception{Field f=MobileStore.class.getDeclaredField("doc");f.setAccessible(true);f.set(null,null);}
 public static void main(String[] args)throws Exception{
  JSONObject fixture=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));JSONObject original=fixture.getJSONObject("before"),actual=MobileStore.copy(original);JSONArray ops=fixture.getJSONArray("operations");for(int i=0;i<ops.length();i++)MobileStore.apply(actual,ops.getJSONObject(i));JSONObject expected=fixture.getJSONObject("after");
  for(String key:new String[]{"quests","items","settings"})check(actual.getJSONObject(key).similar(expected.getJSONObject(key)),"Java and C# agree: "+key);
  check(actual.getLong("balance")==expected.getLong("balance"),"Java and C# agree on rewards and spending");
  check(actual.getJSONObject("purchases").length()==expected.getJSONObject("purchases").length(),"Purchase counts agree");
  java.util.Set<String> a=new java.util.HashSet<>(),b=new java.util.HashSet<>();for(Object x:actual.getJSONArray("rewarded"))a.add((String)x);for(Object x:expected.getJSONArray("rewarded"))b.add((String)x);check(a.equals(b),"Reward claim sets agree");
  Context c=new Context(new File(args[1]));String id=MobileStore.id();JSONObject create=op("create",id).put("value",new JSONObject().put("id",id).put("title","Offline quest").put("notes","").put("parentId","").put("order",0).put("kind",2).put("today",true).put("customReward",JSONObject.NULL).put("done",new JSONObject().put("value",false).put("stamp","")));
  MobileStore.command(c,create.toString());check(state(c).getJSONObject("quests").has(id)&&view(c).getJSONArray("queue").length()==1,"Offline creation is stored with its outbox");forget();check(view(c).getJSONArray("queue").length()==1,"Outbox survives process restart");
  MobileStore.command(c,op("complete",id).put("value",true).toString());check(state(c).getLong("balance")==5,"Offline completion predicts reward");MobileStore.command(c,op("complete",id).put("value",false).toString());MobileStore.command(c,op("complete",id).put("value",true).toString());check(state(c).getLong("balance")==5,"Offline reopen cannot farm rewards");
  MobileStore.command(c,new JSONObject().put("kind","pin").put("value",id).toString());JSONObject notification=MobileStore.notificationState(c);check(notification.getJSONObject("quest").getString("id").equals(id)&&notification.getJSONObject("quest").getBoolean("done"),"Offline local pin uses the phone journal rather than the PC cache");
  JSONObject current=state(c);String oldTitle=current.getJSONObject("quests").getJSONObject(id).getString("title");android.util.AtomicFile.failNext=true;boolean failed=false;try{MobileStore.command(c,op("set",id).put("field","title").put("value","Unsaved").toString());}catch(IOException e){failed=true;}check(failed&&state(c).getJSONObject("quests").getJSONObject(id).getString("title").equals(oldTitle),"Disk failure does not expose an unsaved local edit");
  JSONObject snapshot=state(c);JSONArray ack=new JSONArray();for(Object o:view(c).getJSONArray("queue"))ack.put(((JSONObject)o).getString("id"));PhoneClient.response=new PhoneClient.Response(200,new JSONObject().put("protocol",2).put("state",snapshot).put("ack",ack).put("revision","first"));
  PhoneClient.during=()->{try{MobileStore.command(c,op("set",id).put("field","notes").put("value","Typed while syncing").toString());}catch(Exception e){throw new RuntimeException(e);}};MobileStore.sync(c,null);check(view(c).getJSONArray("queue").length()==1&&state(c).getJSONObject("quests").getJSONObject(id).getString("notes").equals("Typed while syncing"),"Edits during a network request survive acknowledgement");
  JSONObject pending=view(c).getJSONArray("queue").getJSONObject(0);JSONObject remote=MobileStore.copy(snapshot);remote.getJSONObject("quests").getJSONObject(id).put("notes","Edited on PC");PhoneClient.response=new PhoneClient.Response(409,new JSONObject().put("protocol",2).put("state",remote).put("conflict",new JSONObject().put("opId",pending.getString("id")).put("target",id).put("field","notes").put("code","changed").put("pc","Edited on PC")));MobileStore.sync(c,null);check(view(c).has("conflict")&&view(c).getJSONArray("queue").length()==1,"Conflicts retain the pending edit");MobileStore.resolve(c,true);check(!view(c).has("conflict")&&view(c).getJSONArray("queue").getJSONObject(0).getString("base").equals("Edited on PC"),"Phone choice explicitly rebases the pending field");
  String exported=MobileStore.export(c);MobileStore.restore(c,new ByteArrayInputStream(exported.getBytes("UTF-8")));check(view(c).getJSONArray("queue").length()==1,"Backup restores pending edits too");failed=false;try{MobileStore.restore(c,new ByteArrayInputStream("{}".getBytes("UTF-8")));}catch(Exception e){failed=true;}check(failed&&view(c).getJSONArray("queue").length()==1,"Invalid backup preserves the existing journal");
  String beforeRestore=MobileStore.export(c);JSONObject beforeState=state(c);JSONArray beforeAck=new JSONArray();for(Object o:view(c).getJSONArray("queue"))beforeAck.put(((JSONObject)o).getString("id"));PhoneClient.response=new PhoneClient.Response(200,new JSONObject().put("protocol",2).put("state",beforeState).put("ack",beforeAck));PhoneClient.during=()->{try{MobileStore.restore(c,new ByteArrayInputStream(beforeRestore.getBytes("UTF-8")));}catch(Exception e){throw new RuntimeException(e);}};MobileStore.sync(c,null);check(view(c).getJSONArray("queue").length()==1,"An in-flight reply cannot overwrite a restored journal");
  PhoneClient.prefs(c).putString("token","old-token");PhoneClient.during=()->PhoneClient.prefs(c).putString("token","new-token");MobileStore.sync(c,null);check(view(c).getJSONArray("queue").length()==1&&PhoneClient.prefs(c).getString("token","").equals("new-token"),"A reply from an old pairing cannot overwrite a new connection");
  MobileStore.reset(c);check(state(c).getJSONObject("quests").length()==0&&!PhoneClient.prefs(c).m.containsKey("token"),"Reset affects only local journal and pairing");check(new File(c.getFilesDir(),"before-reset.json").isFile(),"Reset retains a recovery copy");
  System.out.println(count+" Android model and cross-platform checks passed");
 }
}